<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Correspondências Sponte • Liceu Brasil</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}.top{height:68px;background:linear-gradient(90deg,#0a55a6,#0b63bd);color:#fff;display:flex;align-items:center;padding:0 22px;gap:14px;position:sticky;top:0;z-index:20;box-shadow:0 4px 18px #0f172a1f}.back{border:1px solid #ffffff44;background:#ffffff14;color:#fff;border-radius:9px;padding:9px 12px;text-decoration:none;font-weight:800}.title strong{display:block;font-size:16px}.title span{font-size:12px;opacity:.72}.wrap{max-width:1450px;margin:22px auto;padding:0 18px}.tabs{display:flex;gap:8px;margin-bottom:16px}.tab{border:1px solid #dbe4ef;background:#fff;border-radius:10px;padding:10px 14px;font-weight:800;color:#526078;cursor:pointer}.tab.active{background:#0b63bd;color:#fff;border-color:#0b63bd}.toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap;background:#fff;border:1px solid #e4eaf2;border-radius:14px;padding:14px;margin-bottom:14px}.field{display:flex;flex-direction:column;gap:5px}.field label{font-size:11px;text-transform:uppercase;font-weight:900;color:#78859a}.field input,.field select{height:40px;border:1px solid #d9e1eb;border-radius:9px;padding:0 11px;min-width:220px;background:#fff}.stats{display:flex;gap:9px;margin-left:auto}.pill{background:#eef6ff;color:#0a55a6;padding:9px 12px;border-radius:10px;font-size:12px;font-weight:900}.card{background:#fff;border:1px solid #e3e9f1;border-radius:14px;box-shadow:0 3px 13px #0f172a0b;margin-bottom:12px;overflow:hidden}.card-head{padding:15px 16px;display:grid;grid-template-columns:minmax(220px,1.5fr) 1fr 110px 120px auto;gap:14px;align-items:center;border-bottom:1px solid #edf1f6}.name{font-weight:900;color:#172033}.muted{font-size:12px;color:#7a8799;margin-top:3px}.money{font-weight:900}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef2ff;color:#4351a5;font-size:11px;font-weight:900}.candidates{padding:12px 16px;background:#fbfcfe}.cand{display:grid;grid-template-columns:70px minmax(220px,1fr) minmax(220px,1fr) auto;gap:12px;align-items:center;padding:10px;border:1px solid #e7ecf2;border-radius:10px;background:#fff;margin:7px 0}.score{font-weight:950;color:#0b63bd;font-size:16px}.reason{font-size:11px;color:#7c8796}.btn{border:0;border-radius:9px;padding:9px 12px;font-weight:850;cursor:pointer}.btn-primary{background:#0b63bd;color:#fff}.btn-soft{background:#edf4fb;color:#0b5ca9}.empty{padding:38px;text-align:center;color:#7a8799;background:#fff;border:1px dashed #ccd6e3;border-radius:14px}.cancel-grid{display:grid;grid-template-columns:1.4fr 1fr 120px 1fr 1.1fr auto;gap:12px;align-items:center;padding:13px 16px}.status-ok{color:#0d8a55;font-weight:900}.status-pend{color:#c47b00;font-weight:900}.cancel-cands{grid-column:1/-1;background:#f8fbff;border-top:1px solid #edf1f6;padding:12px 16px}.cancel-cand{display:grid;grid-template-columns:70px minmax(200px,1fr) minmax(220px,1fr) auto;gap:12px;align-items:center;border:1px solid #dfe8f2;background:#fff;border-radius:10px;padding:10px;margin-top:7px}.motivo{width:100%;height:38px;border:1px solid #d9e1eb;border-radius:8px;padding:0 9px}@media(max-width:900px){.card-head,.cand,.cancel-grid{grid-template-columns:1fr}.stats{margin-left:0}.field input,.field select{min-width:160px}}
.active-grid{display:grid;grid-template-columns:minmax(230px,1.4fr) minmax(180px,1fr) minmax(240px,1.5fr) auto;gap:14px;align-items:center;padding:15px 16px}.suggest{background:#f7fbff;border:1px solid #dceaf8;border-radius:10px;padding:10px}.select-turma{height:40px;max-width:360px;width:100%;border:1px solid #d9e1eb;border-radius:8px;background:#fff;padding:0 8px}.badge-red{background:#fff0f0;color:#b42318}.badge-green{background:#ecfdf3;color:#087443}.badge-amber{background:#fff8e6;color:#9a6700}.hint{padding:12px 14px;background:#eef6ff;border:1px solid #d8eaff;border-radius:12px;margin-bottom:12px;color:#36536f;font-size:13px}@media(max-width:900px){.active-grid{grid-template-columns:1fr}}
</style></head><body>
<div class="top"><a class="back" href="index.php">← Mapa</a><div class="title"><strong>Correspondências Sponte</strong><span>Pagamentos, cancelamentos e conciliação de alunos ativos do Sponte</span></div></div>
<div class="wrap">
<div class="tabs"><button id="tabCorr" class="tab active" onclick="trocar('corr')">Correspondências pendentes</button><button id="tabCan" class="tab" onclick="trocar('can')">Cancelamentos</button><button id="tabAtv" class="tab" onclick="trocar('ativos')">Alunos ativos do Sponte</button></div>
<div class="toolbar"><div class="field"><label>Buscar</label><input id="q" type="search" placeholder="Aluno, curso, contrato..." oninput="render()"></div><div class="field" id="catField"><label>Categoria</label><select id="cat" onchange="render()"><option value="">Todas</option><option>Mensalidade</option><option>Taxa de Matrícula</option><option>Cancelamento</option></select></div><div class="field" id="sitField" style="display:none"><label>Situação</label><select id="sit" onchange="render()"><option value="acao">Precisam de ação</option><option value="nao_encontrado">Não encontrados</option><option value="nao_alocado">Não alocados</option><option value="ja_existe">Já existem</option><option value="alocado">Alocados</option><option value="">Todos</option></select></div><div id="uploadBox" style="display:none;align-items:end;gap:8px"><input id="arquivoSponte" type="file" accept=".xml,text/xml,application/xml" style="display:none" onchange="importarAtivos()"><button class="btn btn-primary" onclick="document.getElementById('arquivoSponte').click()">↑ Importar XML de alunos do Sponte</button></div><button class="btn btn-soft" onclick="carregar()">↻ Atualizar</button><div class="stats"><span class="pill" id="stat">0 pendências</span></div></div>
<div id="lista"></div></div>
<script>
const CSRF=<?=json_encode($csrf,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let modo='corr',corr=[],cans=[],ativos=[],agendas=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const date=v=>{if(!v)return '—';const p=v.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:v};
async function get(action){const r=await fetch(`api.php?action=${action}`,{credentials:'same-origin',cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha');return j}
async function post(action,data){const r=await fetch(`api.php?action=${action}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(data)});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha');return j}
async function carregar(){document.getElementById('lista').innerHTML='<div class="empty">Carregando...</div>';try{if(modo==='corr'){const j=await get('correspondencias_sponte');corr=j.itens||[]}else if(modo==='can'){const j=await get('cancelamentos_sponte');cans=j.itens||[]}else{const j=await get('alunos_ativos_sponte');ativos=j.itens||[];agendas=j.agendas||[]}render()}catch(e){document.getElementById('lista').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function trocar(m){modo=m;document.getElementById('tabCorr').classList.toggle('active',m==='corr');document.getElementById('tabCan').classList.toggle('active',m==='can');document.getElementById('tabAtv').classList.toggle('active',m==='ativos');document.getElementById('catField').style.display=m==='corr'?'flex':'none';document.getElementById('sitField').style.display=m==='ativos'?'flex':'none';document.getElementById('uploadBox').style.display=m==='ativos'?'flex':'none';carregar()}
function render(){const q=(document.getElementById('q').value||'').toLowerCase(),cat=document.getElementById('cat').value;const box=document.getElementById('lista');if(modo==='corr'){const itens=corr.filter(x=>(!cat||x.categoria===cat)&&(!q||`${x.nome} ${x.contrato||''} ${x.turma||''}`.toLowerCase().includes(q)));document.getElementById('stat').textContent=`${itens.length} pendência(s)`;if(!itens.length){box.innerHTML='<div class="empty">Nenhuma correspondência pendente com estes filtros.</div>';return}box.innerHTML=itens.map(item=>`<div class="card"><div class="card-head"><div><div class="name">${esc(item.nome)}</div><div class="muted">${esc(item.turma||'Turma não informada')}</div></div><div><span class="badge">${esc(item.categoria||'Financeiro')}</span><div class="muted">Contrato: ${esc(item.contrato||'—')}</div></div><div class="money">${money(item.valor)}</div><div>${date(item.data)}</div><div class="muted">Lanç. #${item.lancamentoId}</div></div><div class="candidates">${(item.candidatos||[]).length?(item.candidatos||[]).map(c=>`<div class="cand"><div class="score">${Math.min(100,c.score)}%</div><div><div class="name">${esc(c.aluno)}</div><div class="reason">${esc((c.razoes||[]).join(' • '))}</div></div><div><strong>${esc(c.curso||'Sem curso')}</strong><div class="muted">${esc([c.dia,c.horario].filter(Boolean).join(' • ')||'Sem horário')}</div></div><div><button class="btn btn-primary" onclick="vincular(${item.id},${c.alunoId},'${esc(item.nome).replace(/'/g,"\\'")}')">Vincular</button></div></div>`).join(''):'<div class="muted">Nenhum candidato seguro encontrado. Cadastre/corrija o aluno ou aguarde mais dados do relatório.</div>'}</div></div>`).join('')}else if(modo==='can'){const itens=cans.filter(x=>!q||`${x.nome} ${x.curso||''} ${x.contrato||''} ${x.motivo||''}`.toLowerCase().includes(q));document.getElementById('stat').textContent=`${itens.length} cancelamento(s)`;if(!itens.length){box.innerHTML='<div class="empty">Nenhum cancelamento registrado.</div>';return}box.innerHTML=itens.map(x=>`<div class="card"><div class="cancel-grid"><div><div class="name">${esc(x.nome)}</div><div class="muted">Sponte: ${esc(x.nomeSponte||'—')}${x.contrato?` • Contrato ${esc(x.contrato)}`:''}</div></div><div><strong>${esc(x.curso||x.turmaSponte||'Matrícula não identificada')}</strong><div class="muted">${esc([x.dia,x.horario].filter(Boolean).join(' • '))}</div></div><div>${date(x.data)}</div><div><span class="${x.statusVinculo==='aplicado'?'status-ok':'status-pend'}">${x.statusVinculo==='aplicado'?'✓ Aplicado':'⚠ Pendente'}</span><div class="muted">${esc(x.metodoVinculo||'')}</div>${x.statusVinculo!=='aplicado'&&(x.matriculasAtivas||[]).length?`<select class="motivo" id="mat-${x.id}" style="margin-top:6px"><option value="">Escolher matrícula...</option>${x.matriculasAtivas.map(m=>`<option value="${m.matriculaId}">${esc(m.curso)} • ${esc([m.dia,m.horario].filter(Boolean).join(' • '))}</option>`).join('')}</select><button class="btn btn-primary" style="margin-top:6px" onclick="aplicarCancel(${x.id})">Aplicar cancelamento</button>`:''}</div><div><input class="motivo" id="mot-${x.id||('m'+x.matriculaId)}" value="${esc(x.motivo||'')}" placeholder="Motivo (opcional)"></div><div><button class="btn btn-soft" onclick="salvarMotivo(${x.id||0},${x.matriculaId||0})">Salvar motivo</button></div></div>${x.statusVinculo!=='aplicado'&&(x.candidatos||[]).length?`<div class="cancel-cands"><strong>Possíveis correspondências</strong><div class="muted">O sistema cruzou nome, curso, dia e horário. Confirme somente a matrícula correta.</div>${x.candidatos.map(c=>`<div class="cancel-cand"><div class="score">${Math.min(100,c.score)}%</div><div><div class="name">${esc(c.aluno)}</div><div class="reason">${esc((c.razoes||[]).join(' • '))}</div></div><div><strong>${esc(c.curso||'Sem curso')}</strong><div class="muted">${esc([c.dia,c.horario].filter(Boolean).join(' • ')||'Sem horário')}</div></div><div><button class="btn btn-primary" onclick="confirmarCancelCandidato(${x.id},${c.alunoId},${c.matriculaId})">Confirmar cancelamento</button></div></div>`).join('')}</div>`:''}</div>`).join('')}else{const sit=document.getElementById('sit').value;const itens=ativos.filter(x=>{const acao=x.situacao==='nao_encontrado'||x.situacao==='nao_alocado'||(x.situacao==='ja_existe'&&Number(x.matriculasAtivas||0)===0);return (!q||`${x.nome} ${x.cpf||''} ${x.email||''} ${x.turmaSponte||''}`.toLowerCase().includes(q))&&(!sit||(sit==='acao'?acao:x.situacao===sit))});document.getElementById('stat').textContent=`${itens.length} aluno(s)`;if(!ativos.length){box.innerHTML='<div class="hint"><strong>Importe o XML de Cadastro de Alunos do Sponte.</strong> O sistema considera somente quem estiver com situação Ativo, cruza com o Mapa e não cria matrícula automaticamente.</div><div class="empty">Nenhuma lista de alunos ativos foi importada ainda.</div>';return}if(!itens.length){box.innerHTML='<div class="empty">Nenhum aluno neste filtro.</div>';return}box.innerHTML='<div class="hint"><strong>Conciliação Sponte → Mapa:</strong> alunos já existentes não são duplicados. Para os que precisam de ação, escolha uma sugestão ou qualquer turma disponível. Você também pode incluir o cadastro sem turma e alocar depois.</div>'+itens.map(x=>{const badge=x.situacao==='nao_encontrado'?'<span class="badge badge-red">Não encontrado no Mapa</span>':x.situacao==='nao_alocado'?'<span class="badge badge-amber">Não alocado</span>':x.situacao==='alocado'?'<span class="badge badge-green">Alocado</span>':Number(x.matriculasAtivas||0)>0?'<span class="badge badge-green">Já existe no Mapa</span>':'<span class="badge badge-amber">Existe, sem matrícula ativa</span>';const opts=agendas.map(a=>`<option value="${a.agendaId}">${esc(a.turma)} • ${esc(a.dia)} • ${esc(a.horario)} • ${esc(a.tipoCurso)}${a.vagas!==undefined?' • '+a.vagas+' vaga(s)':''}</option>`).join('');const sugs=(x.sugestoes||[]).map(a=>`<button class="btn btn-soft" style="margin:3px" onclick="document.getElementById('ag-${x.id}').value='${a.agendaId}'">${a.score}% • ${esc(a.turma)} • ${esc(a.dia)} ${esc(a.horario)}</button>`).join('');const pode=x.situacao!=='alocado';return `<div class="card"><div class="active-grid"><div><div class="name">${esc(x.nome)}</div><div class="muted">${esc(x.cpf||'CPF não informado')} • ${esc(x.telefone||'sem telefone')}</div><div class="muted">${esc(x.email||'')}</div>${badge}</div><div><strong>Sponte</strong><div class="muted">${x.numeroMatricula?'Matrícula '+esc(x.numeroMatricula)+' • ':''}${x.sponteAlunoId?'ID '+esc(x.sponteAlunoId):''}</div><div class="muted">${esc(x.turmaSponte||'O XML não trouxe turma')}</div>${x.alunoMapa?`<div class="muted">Mapa: ${esc(x.alunoMapa)} • ${x.matriculasAtivas} matrícula(s) ativa(s)</div>`:''}</div><div class="suggest"><strong>Turma no Mapa</strong>${sugs?`<div class="muted">Sugestões encontradas:</div><div>${sugs}</div>`:'<div class="muted">Escolha uma turma para alocar:</div>'}<select class="select-turma" id="ag-${x.id}"><option value="">Selecionar turma...</option>${opts}</select></div><div>${pode?`<button class="btn btn-primary" onclick="incluirAtivo(${x.id})">Incluir / Alocar</button><button class="btn btn-soft" style="margin-top:6px" onclick="incluirAtivo(${x.id},true)">Incluir sem turma</button>`:'<span class="status-ok">✓ Resolvido</span>'}</div></div></div>`}).join('')}}
async function vincular(id,alunoId,nome){const todos=confirm(`Vincular este pagamento de ${nome} ao aluno escolhido?\n\nOK = vincular TODOS os pagamentos pendentes com o mesmo nome do XML.\nCancelar = apenas este lançamento.`);try{await post('vincular_correspondencia_sponte',{pagamentoId:id,alunoId,aplicarMesmoNome:todos});await carregar()}catch(e){alert(e.message)}}
async function aplicarCancel(id){const el=document.getElementById(`mat-${id}`);const matriculaId=Number(el&&el.value||0);if(!matriculaId){alert('Escolha a matrícula correta.');return}if(!confirm('Aplicar este cancelamento à matrícula selecionada?'))return;try{await post('aplicar_cancelamento_sponte_manual',{id,matriculaId});await carregar()}catch(e){alert(e.message)}}
async function confirmarCancelCandidato(id,alunoId,matriculaId){if(!confirm('Confirmar que este cancelamento pertence a este aluno e a esta matrícula?\n\nA matrícula será marcada como cancelada e sairá do Radar ativo.'))return;try{await post('aplicar_cancelamento_sponte_manual',{id,alunoId,matriculaId});await carregar()}catch(e){alert(e.message)}}
async function salvarMotivo(id,matriculaId){try{await post('atualizar_motivo_cancelamento_sponte',{id,matriculaId,motivo:document.getElementById(`mot-${id||('m'+matriculaId)}`).value});await carregar()}catch(e){alert(e.message)}}

async function importarAtivos(){
 const input=document.getElementById('arquivoSponte'),f=input.files&&input.files[0];if(!f)return;
 if(!/\.xml$/i.test(f.name)){alert('Selecione um arquivo XML exportado do Cadastro de Alunos do Sponte.');input.value='';return}
 const box=document.getElementById('lista'),chunkSize=1024*1024,total=Math.ceil(f.size/chunkSize);
 const uploadId='sp_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10);
 try{
   for(let i=0;i<total;i++){
     const pct=Math.round((i/total)*100);box.innerHTML=`<div class="empty"><strong>Enviando ${esc(f.name)}</strong><br>${pct}% • bloco ${i+1} de ${total}<br><span class="muted">O arquivo é enviado em blocos para funcionar mesmo com o limite de upload da hospedagem.</span></div>`;
     const fd=new FormData();fd.append('upload_id',uploadId);fd.append('indice',String(i));fd.append('chunk',f.slice(i*chunkSize,Math.min(f.size,(i+1)*chunkSize)),'parte.bin');
     const r=await fetch('api.php?action=upload_chunk_alunos_sponte',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':CSRF},body:fd});
     const txt=await r.text();let j;try{j=JSON.parse(txt)}catch(_){throw new Error('O servidor devolveu uma resposta inválida ao enviar o bloco '+(i+1)+'.')};if(!r.ok||!j.ok)throw new Error(j.error||'Falha ao enviar o XML');
   }
   box.innerHTML=`<div class="empty"><strong>${esc(f.name)} enviado.</strong><br>Lendo XML e cruzando alunos ativos do Sponte...</div>`;
   const fd=new FormData();fd.append('upload_id',uploadId);fd.append('original_name',f.name);
   const r=await fetch('api.php?action=importar_alunos_ativos_sponte',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':CSRF},body:fd});const txt=await r.text();let j;try{j=JSON.parse(txt)}catch(_){throw new Error('O servidor interrompeu o processamento do XML. Tente novamente; se persistir, envie o erro para análise.')};if(!r.ok||!j.ok)throw new Error(j.error||'Falha na importação');
   alert(`Importação concluída.\n\n${j.ativos} ativos no Sponte\n${j.novos} precisam ser incluídos\n${j.existentes} já existem no Mapa\n${j.comTurma||0} com turma informada`);await carregar();
 }catch(e){alert(e.message);await carregar()}finally{input.value=''}
}
async function incluirAtivo(id,semTurma=false){const agendaId=semTurma?0:Number(document.getElementById(`ag-${id}`)?.value||0);if(!semTurma&&!agendaId){alert('Escolha a turma/alocação no Mapa ou use “Incluir sem turma”.');return}if(!confirm(semTurma?'Incluir este aluno no Mapa sem turma? Ele ficará como Não alocado.':'Incluir/alocar este aluno na turma selecionada?'))return;try{await post('incluir_aluno_sponte',{id,agendaId});await carregar()}catch(e){alert(e.message)}}
carregar();
</script></body></html>
